import math

def trapezoid(f, a, b, n):
    dx = (b - a) / n
    return dx * (f(a) / 2 + sum(f(a + i * dx) for i in range(1, n)) + f(b) / 2)

def simpson(f, a, b, n):                       # n must be even
    dx = (b - a) / n
    return dx / 3 * (f(a) + f(b) + sum((4 if i % 2 else 2) * f(a + i * dx) for i in range(1, n)))

f = lambda x: math.exp(-x * x)
exact = math.sqrt(math.pi) / 2 * math.erf(1)
print(f"trapezoid error {trapezoid(f, 0, 1, 10) - exact:.2e}, Simpson error {simpson(f, 0, 1, 10) - exact:.2e}")
